const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check cart tables schema
const cartCols = db.prepare(\"PRAGMA table_info(carts)\").all();
console.log('carts columns:', cartCols.map(c => c.name));

const cartItemCols = db.prepare(\"PRAGMA table_info(cart_items)\").all();
console.log('cart_items columns:', cartItemCols.map(c => c.name));

// Check if user already has a cart
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = ? OR user_id = ?\").all('user_d3d5d0c8', 'user_d3d5d0c8');
console.log('\\nExisting cart:', JSON.stringify(cart, null, 2));
"

